CREATE POLICY "Hosts read alteration photos" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='alteration-photos' AND public.is_celebration_host((storage.foldername(name))[1]::uuid));
CREATE POLICY "Hosts upload alteration photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='alteration-photos' AND public.is_celebration_host((storage.foldername(name))[1]::uuid));
CREATE POLICY "Hosts delete alteration photos" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='alteration-photos' AND public.is_celebration_host((storage.foldername(name))[1]::uuid));